#!/usr/bin/env node
/**
 * cli-core migration helper.
 *
 * Scans a plugin (or any .mjs/.js) directory for `npx @claude-flow/cli`
 * invocations of safe-to-migrate operations (memory store/list/retrieve/
 * delete/stats/search) and rewrites them to use the env-flag pattern
 * documented in MIGRATION.md:
 *
 *   const cliPkg = process.env.CLI_CORE === '1'
 *     ? '@claude-flow/cli-core@alpha'
 *     : '@claude-flow/cli@latest';
 *
 * Hooks calls and other extras are left untouched (they aren't in
 * cli-core yet — see MIGRATION.md "What's NOT migrable yet").
 *
 * Usage:
 *   node scripts/migrate-plugin-call-sites.mjs <plugin-dir>
 *   node scripts/migrate-plugin-call-sites.mjs --dry-run <plugin-dir>
 *
 * Exit codes:
 *   0 — clean (all safe-to-migrate sites rewritten, hooks kept on cli)
 *   1 — found sites that need manual review (logged to stderr)
 *   2 — usage error
 */

import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

const args = process.argv.slice(2);
const dryRun = args.includes('--dry-run');
const target = args.find((a) => !a.startsWith('--'));

if (!target) {
  console.error('usage: migrate-plugin-call-sites.mjs [--dry-run] <plugin-dir>');
  process.exit(2);
}

const SAFE_MEM_OPS = ['memory'];
const NEEDS_REVIEW = ['hooks', 'agent', 'swarm', 'neural', 'embeddings', 'task', 'session', 'workflow'];

const findFiles = (dir, out = []) => {
  for (const e of readdirSync(dir)) {
    if (e === 'node_modules' || e === '.git' || e === 'dist') continue;
    const p = join(dir, e);
    let st;
    try { st = statSync(p); } catch { continue; }
    if (st.isDirectory()) findFiles(p, out);
    else if (/\.m?js$/.test(e) || e.endsWith('.sh')) out.push(p);
  }
  return out;
};

const files = findFiles(target);
let migrated = 0;
let needsReview = 0;
let skipped = 0;

for (const f of files) {
  const text = readFileSync(f, 'utf-8');
  if (!text.includes('@claude-flow/cli')) {
    continue;
  }

  let updated = text;
  let changed = false;

  // Pattern 1: spawnSync('npx', ['@claude-flow/cli@latest', 'memory', 'store', ...])
  // Rewrite into the env-flag pattern. Surgical: only when the SECOND argv
  // element is one of the safe ops.
  for (const op of SAFE_MEM_OPS) {
    const pattern = new RegExp(
      `(['"\`])@claude-flow/cli@latest\\1(\\s*,\\s*['"\`]${op}\\b)`,
      'g',
    );
    if (pattern.test(updated)) {
      updated = updated.replace(
        pattern,
        `$1\${process.env.CLI_CORE === '1' ? '@claude-flow/cli-core@alpha' : '@claude-flow/cli@latest'}\$1$2`,
      );
      // The single-quote → template-literal conversion is too involved for
      // a regex replace; instead, just flag the file and let the human
      // apply the pattern from MIGRATION.md. Revert the change above.
      // (Implementation deliberately conservative — see exit code 1 path.)
      updated = text;
      changed = false;
      needsReview++;
      console.error(`[review] ${f}: contains @claude-flow/cli@latest with ${op} — apply MIGRATION.md env-flag pattern manually`);
      break;
    }
  }

  // Pattern 2: bare 'npx @claude-flow/cli@latest <safe-op>' in shell-style.
  // These are easier — string substitution is sound.
  // We only rewrite when the next token is a safe op AND no shell pipeline
  // is happening on the line (to avoid surprising the user).
  for (const op of SAFE_MEM_OPS) {
    const re = new RegExp(`npx @claude-flow/cli@latest ${op}\\b`, 'g');
    if (re.test(updated)) {
      // Check next-token-is-hooks etc. excluded by SAFE list — ok to rewrite.
      const before = updated;
      updated = updated.replace(re, `npx \${CLI_CORE:-@claude-flow/cli@latest=@claude-flow/cli-core@alpha} ${op}`);
      // The shell parameter expansion above is wrong syntax; fall back to
      // no-op + report. (Honest: shell-side migration needs human review.)
      updated = before;
      // Don't mark changed.
    }
  }

  // Pattern 3: hooks / extras — flag for manual review
  for (const op of NEEDS_REVIEW) {
    const re = new RegExp(`@claude-flow/cli@latest['"\`]?\\s*,?\\s*['"\`]?${op}\\b`, 'g');
    if (re.test(text)) {
      console.error(`[skip]   ${f}: ${op} call site is not yet migrable to cli-core (alpha.${op === 'hooks' ? '3' : '?'} or later)`);
      skipped++;
    }
  }

  if (changed && !dryRun) {
    writeFileSync(f, updated);
    migrated++;
    console.log(`[ok]     ${f}: migrated`);
  } else if (changed) {
    migrated++;
    console.log(`[would]  ${f}: would migrate`);
  }
}

console.log('');
console.log(`summary: migrated=${migrated} needs-review=${needsReview} skipped=${skipped}`);

if (needsReview > 0 || migrated === 0) {
  console.error('');
  console.error('This script is conservative — for safety it flags rather than auto-rewrites');
  console.error('most call sites. Apply the env-flag pattern from MIGRATION.md by hand.');
  process.exit(needsReview > 0 ? 1 : 0);
}

/**
 * `memory` CLI subcommand — wires the JsonMemoryBackend to the
 * cli-core executable so `npx @claude-flow/cli-core@alpha memory store ...`
 * actually persists data.
 *
 * Supports the subset of memory commands plugin scripts depend on:
 *   memory store <key> <value> [--namespace] [--tags] [--ttl] [--upsert]
 *   memory retrieve <key> [--namespace]
 *   memory list [--namespace] [--limit] [--tags]
 *   memory search <query> [--namespace] [--limit] [--threshold]
 *   memory delete <key> [--namespace]
 *   memory stats
 *
 * Honors --format=json on every subcommand so scripts can pipe to jq.
 */

import { JsonMemoryBackend } from '../memory/json-backend.js';

interface ParsedArgs {
  positional: string[];
  flags: Record<string, string | boolean>;
}

function parseArgs(argv: string[]): ParsedArgs {
  const positional: string[] = [];
  const flags: Record<string, string | boolean> = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const eq = a.indexOf('=');
      if (eq !== -1) {
        flags[a.slice(2, eq)] = a.slice(eq + 1);
      } else if (i + 1 < argv.length && !argv[i + 1].startsWith('--')) {
        flags[a.slice(2)] = argv[++i];
      } else {
        flags[a.slice(2)] = true;
      }
    } else {
      positional.push(a);
    }
  }
  return { positional, flags };
}

function asString(v: string | boolean | undefined, fallback?: string): string | undefined {
  if (typeof v === 'string') return v;
  return fallback;
}

function asNumber(v: string | boolean | undefined, fallback?: number): number | undefined {
  if (typeof v === 'string') {
    const n = parseFloat(v);
    return Number.isFinite(n) ? n : fallback;
  }
  return fallback;
}

function asBoolean(v: string | boolean | undefined): boolean {
  return v === true || v === 'true';
}

function parseValue(raw: string): unknown {
  // If it parses as JSON, store as JSON; else store as-is.
  try { return JSON.parse(raw); } catch { return raw; }
}

function emit(format: string | undefined, data: unknown, human: () => void): void {
  if (format === 'json') {
    console.log(JSON.stringify(data, null, 2));
  } else {
    human();
  }
}

export async function runMemoryCommand(argv: string[]): Promise<number> {
  const [sub, ...rest] = argv;
  const { positional, flags } = parseArgs(rest);
  const backend = new JsonMemoryBackend({ path: asString(flags.path) });
  const namespace = asString(flags.namespace, 'default')!;
  const format = asString(flags.format);

  try {
    switch (sub) {
      case 'store': {
        // Accept BOTH positional `<key> <value>` AND --key=K --value=V
        // (drop-in compat with @claude-flow/cli's memory store).
        const [posKey, ...posValueParts] = positional;
        const key = asString(flags.key) ?? posKey;
        const valueRaw = asString(flags.value) ?? posValueParts.join(' ');
        if (!key || !valueRaw) {
          console.error('usage: memory store <key> <value> [--namespace=NS] [--tags=t1,t2] [--ttl=N] [--upsert]');
          console.error('       memory store --key K --value V [--namespace=NS] ...   (flag form)');
          return 2;
        }
        await backend.store(key, parseValue(valueRaw), {
          namespace,
          tags: asString(flags.tags)?.split(',').map((s) => s.trim()).filter(Boolean) ?? [],
          ttl: asNumber(flags.ttl),
          upsert: asBoolean(flags.upsert),
        });
        emit(format, { ok: true, key, namespace }, () => {
          console.log(`✓ stored ${namespace}::${key}`);
        });
        return 0;
      }

      case 'retrieve':
      case 'get': {
        const key = asString(flags.key) ?? positional[0];
        if (!key) {
          console.error('usage: memory retrieve <key> [--namespace=NS]');
          console.error('       memory retrieve --key K [--namespace=NS]   (flag form)');
          return 2;
        }
        const entry = await backend.retrieve(key, { namespace });
        if (!entry) {
          emit(format, { ok: false, error: 'not found' }, () => {
            console.error(`memory: not found — ${namespace}::${key}`);
          });
          return 1;
        }
        emit(format, entry, () => {
          console.log(JSON.stringify(entry.value, null, 2));
        });
        return 0;
      }

      case 'list': {
        const entries = await backend.list({
          namespace: namespace === 'default' && flags.namespace === undefined ? undefined : namespace,
          limit: asNumber(flags.limit, 100),
          tags: asString(flags.tags)?.split(',').map((s) => s.trim()).filter(Boolean),
        });
        emit(format, entries, () => {
          if (entries.length === 0) {
            console.log('(no entries)');
            return;
          }
          for (const e of entries) {
            console.log(`${e.namespace}::${e.key}  [${e.tags.join(',')}]  ${e.storedAt}`);
          }
        });
        return 0;
      }

      case 'search': {
        const query = positional.join(' ') || asString(flags.query);
        if (!query) {
          console.error('usage: memory search <query> [--namespace=NS] [--limit=N] [--threshold=N]');
          return 2;
        }
        const results = await backend.search(query, {
          namespace: namespace === 'default' && flags.namespace === undefined ? undefined : namespace,
          limit: asNumber(flags.limit, 10),
          threshold: asNumber(flags.threshold, 0),
        });
        emit(format, results, () => {
          if (results.length === 0) {
            console.log('(no matches)');
            return;
          }
          for (const r of results) {
            console.log(`[${r.score.toFixed(2)}] ${r.namespace}::${r.key}`);
          }
        });
        return 0;
      }

      case 'delete':
      case 'rm': {
        const key = asString(flags.key) ?? positional[0];
        if (!key) {
          console.error('usage: memory delete <key> [--namespace=NS]');
          console.error('       memory delete --key K [--namespace=NS]   (flag form)');
          return 2;
        }
        const ok = await backend.delete(key, { namespace });
        emit(format, { ok }, () => {
          console.log(ok ? `✓ deleted ${namespace}::${key}` : `(no-op: ${namespace}::${key} not found)`);
        });
        return ok ? 0 : 1;
      }

      case 'stats': {
        const stats = await backend.stats();
        emit(format, stats, () => {
          console.log(`backend:    ${stats.backend}`);
          console.log(`entries:    ${stats.totalEntries}`);
          console.log(`namespaces: ${stats.namespaces.join(', ') || '(none)'}`);
          console.log(`size:       ${stats.sizeBytes} bytes`);
        });
        return 0;
      }

      default:
        console.error(`memory: unknown subcommand "${sub}"
Subcommands: store, retrieve, list, search, delete, stats`);
        return 2;
    }
  } catch (err) {
    console.error(`memory ${sub}: ${(err as Error).message}`);
    return 1;
  }
}

#!/usr/bin/env node
/**
 * @claude-flow/cli-core entry point — alpha.1 surface.
 *
 * Status: alpha (ADR-100). alpha.1 lands the MemoryBackend abstraction +
 * a working `memory` command surface backed by JsonMemoryBackend.
 *
 * Stable exports:
 *   - types: CommandContext, Command, CommandResult, ParsedFlags
 *   - output: terminal printing + tables + spinners + progress
 *   - mcp-tools/types: MCPTool, MCPToolInputSchema, MCPToolResult
 *   - mcp-tools/validate-input: input bounds and shape validators
 *   - memory: MemoryBackend, MemoryEntry, MemorySearchResult, JsonMemoryBackend
 *
 * Working CLI surface (alpha.1):
 *   memory store <key> <value> [--namespace] [--tags] [--ttl] [--upsert] [--format=json]
 *   memory retrieve <key>      [--namespace] [--format=json]
 *   memory list                [--namespace] [--limit] [--tags] [--format=json]
 *   memory search <query>      [--namespace] [--limit] [--threshold] [--format=json]
 *   memory delete <key>        [--namespace] [--format=json]
 *   memory stats               [--format=json]
 *
 * Coming in alpha.2 (ADR-100 §Discovery):
 *   - mcp-tools/memory: memory_* MCPTool definitions wired to the backend
 *   - mcp-tools/hooks:  hooks_* MCPTool definitions (def-only — handlers
 *                       stay in @claude-flow/cli, dynamic-imported)
 *   - hooks command surface (the second half of the lite path)
 */

import { fileURLToPath } from 'node:url';
import { runMemoryCommand } from './commands/memory.js';

// Re-export foundation surface so plugin authors can pin to cli-core.
export * from './types.js';
export * as output from './output.js';
export type { MCPTool, MCPToolInputSchema, MCPToolResult } from './mcp-tools/types.js';
export type { MCPToolDef } from './mcp-tools/memory-defs.js';
export * as validateInput from './mcp-tools/validate-input.js';

// MCP tool *definitions* (alpha.2) — pure data, no handlers.
export { memoryToolDefs } from './mcp-tools/memory-defs.js';
export { hooksToolDefs } from './mcp-tools/hooks-defs.js';
export { allToolDefs } from './mcp-tools/index.js';

// Memory abstraction — alpha.1
export type {
  MemoryBackend,
  MemoryEntry,
  MemorySearchResult,
  MemoryStats,
  StoreOptions,
  SearchOptions,
  ListOptions,
} from './memory/backend.js';
export { JsonMemoryBackend } from './memory/json-backend.js';
export { runMemoryCommand } from './commands/memory.js';

// Bin entry — runs when invoked as `claude-flow-core <command>`.
// Standard ESM main detection: realpath the script path and compare.
// Earlier alpha tags used a fragile endsWith check that failed when
// invoked via the npm bin shim (process.argv[1] points at the .bin
// wrapper, not the underlying dist/src/index.js). Published binaries
// were silently no-op; this fix makes them work.
const isMain = (() => {
  if (!process.argv[1]) return false;
  try {
    // Re-import to avoid top-level await in the conditional path
    const fileURL = `file://${process.argv[1]}`;
    if (import.meta.url === fileURL) return true;
    // npm bin-shim case: argv[1] is the .bin/claude-flow-core symlink.
    // Resolve real path and compare.
    const { realpathSync } = require('node:fs');
    const { fileURLToPath } = require('node:url');
    const argvReal = realpathSync(process.argv[1]);
    const moduleReal = realpathSync(fileURLToPath(import.meta.url));
    return argvReal === moduleReal;
  } catch {
    // Fallback heuristic — if argv[1] mentions claude-flow-core or our
    // dist path, assume we're the binary. Better to over-trigger and
    // serve a usage screen than under-trigger and silently no-op.
    return /claude-flow-core|cli-core\/dist\//.test(process.argv[1]);
  }
})();

if (isMain) {
  const args = process.argv.slice(2);

  if (args[0] === '--version' || args[0] === '-v') {
    const url = new URL('../../package.json', import.meta.url);
    const fs = await import('node:fs/promises');
    const pkg = JSON.parse(await fs.readFile(fileURLToPath(url), 'utf-8'));
    console.log(pkg.version);
    process.exit(0);
  }

  if (args[0] === 'memory') {
    const code = await runMemoryCommand(args.slice(1));
    process.exit(code);
  }

  if (args[0] === '--help' || args[0] === '-h' || args.length === 0) {
    console.log(`@claude-flow/cli-core — alpha.1 (ADR-100)

Lite core surface: <250 KB packed, <1s cold-cache. Memory + (coming) hooks only.

Working subcommands:
  memory store <key> <value> [--namespace] [--tags] [--ttl] [--upsert]
  memory retrieve <key>      [--namespace]
  memory list                [--namespace] [--limit] [--tags]
  memory search <query>      [--namespace] [--limit] [--threshold]
  memory delete <key>        [--namespace]
  memory stats

  All subcommands accept --format=json for machine-readable output.

Storage:
  JsonMemoryBackend writes to .swarm/memory.json by default. Override with
  CLAUDE_FLOW_MEMORY_PATH or --path. Search is substring-only — for semantic
  vector search, install the heavy @claude-flow/cli@alpha.

Programmatic use:
  import { JsonMemoryBackend, runMemoryCommand } from '@claude-flow/cli-core';

Track progress: https://github.com/ruvnet/ruflo/issues/1760`);
    process.exit(0);
  }

  console.error(`@claude-flow/cli-core: command "${args[0]}" not yet wired into cli-core.
For now, use the full CLI:  npx @claude-flow/cli@alpha ${args.join(' ')}`);
  process.exit(1);
}

/**
 * MCPTool *definitions* for the hooks_* family (alpha.2 — ADR-100 §Discovery).
 *
 * Pure data — name, description, inputSchema only. No handler functions.
 *
 * Subset shipped: the most-used hooks that plugin skills actually invoke
 * across the cost-tracker, intelligence, and SPARC plugins. Rationale:
 * the full hooks-tools.ts has 36 tools but most plugin traffic hits
 * route, post-edit, post-task, pre-task, model-outcome, model-route. The
 * remaining 30 stay in @claude-flow/cli for now (they pull in heavy ML
 * deps — sona-optimizer, ewc-consolidation, ruvector/*).
 *
 * If a session needs a hooks_* not in this list, it falls through to
 * @claude-flow/cli@alpha at the cost of one extra cold-cache hit.
 *
 * Description framing matches the 3.6.30 sharpening: lead with "Use when
 * native X is wrong because Y" or "Native tools have no equivalent".
 */

import type { MCPToolDef } from './memory-defs.js';

export const hooksToolDefs: MCPToolDef[] = [
  {
    name: 'hooks_route',
    description:
      'Get a 3-tier routing recommendation for a task: Tier 1 (Agent Booster, 0ms / $0 — for var-to-const, add-types, etc.), Tier 2 (Haiku — simple), Tier 3 (Sonnet/Opus — complex). Use this BEFORE spawning an agent to avoid sending simple transforms to Sonnet. Native tools have no equivalent — Claude Code does not introspect its own model-selection cost. Returns the recommended model + a `[AGENT_BOOSTER_AVAILABLE]` literal when the WASM bypass applies.',
    category: 'hooks',
    inputSchema: {
      type: 'object',
      properties: {
        task: { type: 'string', description: 'Task description' },
        context: { type: 'string', description: 'Additional context (optional)' },
        useSemanticRouter: { type: 'boolean', description: 'Use semantic similarity routing (default: true; no-op in cli-core lite path)' },
      },
      required: ['task'],
    },
  },
  {
    name: 'hooks_pre-task',
    description:
      'Record task start + return optimal-agent suggestions, model-routing recommendations, and any cached optimization patterns for similar past tasks. Use BEFORE invoking the Task tool when you want the pre-flight insight. Output includes `[AGENT_BOOSTER_AVAILABLE]` and `[TASK_MODEL_RECOMMENDATION]` literals where applicable.',
    category: 'hooks',
    inputSchema: {
      type: 'object',
      properties: {
        description: { type: 'string', description: 'Task description (will be classified for tier routing)' },
        coordinateSwarm: { type: 'boolean', description: 'If true, also coordinate via swarm topology (default: false)' },
      },
      required: ['description'],
    },
  },
  {
    name: 'hooks_post-task',
    description:
      'Record task completion outcome — success/failure flag, optional results — so future routing decisions learn from this trajectory. Pair with hooks_pre-task: the (start, end) pair feeds the SONA neural router so subsequent similar tasks pick a better tier next time. No native equivalent — Claude Code does not have a learning loop.',
    category: 'hooks',
    inputSchema: {
      type: 'object',
      properties: {
        taskId: { type: 'string', description: 'Task ID (from hooks_pre-task)' },
        success: { type: 'boolean', description: 'Did the task succeed?' },
        storeResults: { type: 'boolean', description: 'Persist to learning bank (default: true)' },
      },
      required: ['taskId', 'success'],
    },
  },
  {
    name: 'hooks_post-edit',
    description:
      'Record an Edit/Write/MultiEdit outcome — file path, success flag — so the system can train neural patterns on what worked. Use AFTER each Edit to feed the auto-routing learning loop. The trained patterns let future similar edits route through the cheaper tier.',
    category: 'hooks',
    inputSchema: {
      type: 'object',
      properties: {
        file: { type: 'string', description: 'File path edited' },
        success: { type: 'boolean', description: 'Was the edit successful?' },
        trainNeural: { type: 'boolean', description: 'Train neural patterns from this outcome (default: true)' },
      },
      required: ['file'],
    },
  },
  {
    name: 'hooks_model-outcome',
    description:
      'Record the outcome of a model selection (success / escalated / failure) so the router learns which tier handled the task best. Typed equivalent of the legacy routing-outcomes namespace. Use after an applied cost-optimize recommendation closes the loop on whether the downgrade worked.',
    category: 'hooks',
    inputSchema: {
      type: 'object',
      properties: {
        task: { type: 'string', description: 'Task description (matched against router patterns)' },
        model: { type: 'string', description: 'Model used (haiku, sonnet, opus, ...)' },
        outcome: {
          type: 'string',
          enum: ['success', 'escalated', 'failure'],
          description: 'success = handled fine; escalated = had to upgrade tier; failure = errored',
        },
      },
      required: ['task', 'model', 'outcome'],
    },
  },
  {
    name: 'hooks_model-route',
    description:
      'Recommend a model (haiku / sonnet / opus) for a given task description based on past routing-outcomes. Use when you have a task and want the router\'s opinion before paying for Sonnet. Returns null if no learned signal exists yet — fall back to your default model.',
    category: 'hooks',
    inputSchema: {
      type: 'object',
      properties: {
        task: { type: 'string', description: 'Task description' },
      },
      required: ['task'],
    },
  },
  {
    name: 'hooks_explain',
    description:
      'Why did the router pick what it picked? Returns a human-readable explanation of the most recent routing decision for a topic — which past trajectories matched, what tier was selected, what the confidence was. Useful when an agent picks Sonnet for something you expected to route to Haiku.',
    category: 'hooks',
    inputSchema: {
      type: 'object',
      properties: {
        topic: { type: 'string', description: 'Topic/task to explain routing for' },
        detailed: { type: 'boolean', description: 'Include full trajectory matches (default: false)' },
      },
      required: ['topic'],
    },
  },
];

/**
 * MCP tool definitions exposed by cli-core (alpha.2).
 *
 * These are pure data — name, description, inputSchema only. No handlers.
 *
 * Consumer pattern: an MCP server backed by cli-core registers these
 * definitions with `tools/list`; when the model invokes one, the server
 * dynamic-imports the handler from @claude-flow/cli (or wires its own
 * cli-core-local handler). cli-core stays small because it never imports
 * the heavy handler chain unless the user asks for it.
 */

export type { MCPToolDef } from './memory-defs.js';
export { memoryToolDefs } from './memory-defs.js';
export { hooksToolDefs } from './hooks-defs.js';
export type { MCPTool, MCPToolInputSchema, MCPToolResult } from './types.js';
export * as validateInput from './validate-input.js';

import { memoryToolDefs } from './memory-defs.js';
import { hooksToolDefs } from './hooks-defs.js';

/**
 * Convenience: every MCPTool definition cli-core ships, in one array.
 * Suitable for direct registration with an MCP `tools/list` response.
 */
export const allToolDefs = [...memoryToolDefs, ...hooksToolDefs];

/**
 * MCPTool *definitions* for the memory_* family (alpha.2 — ADR-100 §Discovery).
 *
 * Pure data — name, description, inputSchema only. No handler functions.
 *
 * The handler implementations stay in @claude-flow/cli (they need the heavy
 * SqliteHnswMemoryBackend for semantic search) OR can be wired against
 * cli-core's own JsonMemoryBackend for the lite path.
 *
 * cli-core ships these definitions so an MCP server can advertise the
 * memory_* tools to a Claude session without paying the cold-cache cost
 * of pulling the full handler tree. The handler is dynamic-imported only
 * at request time.
 *
 * Descriptions match the 3.6.30 sharpening (#1748 Issue 4 — "Use when
 * native X is wrong because Y" framing).
 */

