/**
 * MCP Tool Types for CLI
 *
 * Local type definitions to avoid external imports outside package boundary.
 */

export interface MCPToolInputSchema {
  type: 'object';
  properties: Record<string, unknown>;
  required?: string[];
}

export interface MCPToolResult {
  content: Array<{
    type: 'text' | 'image' | 'resource';
    text?: string;
    data?: string;
    mimeType?: string;
  }>;
  isError?: boolean;
}

/**
 * Returns the effective project working directory.
 * Prefers CLAUDE_FLOW_CWD (set by the install script for global/MCP installs
 * where process.cwd() may resolve to '/') over the real process.cwd().
 */
export function getProjectCwd(): string {
  const envCwd = process.env.CLAUDE_FLOW_CWD;
  if (envCwd && envCwd !== '/' && envCwd !== process.env.HOME) {
    return envCwd;
  }
  return process.cwd();
}

export interface MCPTool {
  name: string;
  description: string;
  inputSchema: MCPToolInputSchema;
  category?: string;
  tags?: string[];
  version?: string;
  cacheable?: boolean;
  cacheTTL?: number;
  handler: (input: Record<string, unknown>, context?: Record<string, unknown>) => Promise<MCPToolResult | unknown>;
}

/**
 * Input Validation for MCP Tools
 *
 * Loads @claude-flow/security validators when available
 * and provides lightweight fallback validation otherwise.
 *
 * Addresses #1425: security validators were implemented but never wired to runtime.
 */

// Patterns for input sanitization (inline — no external dependency required)
const SHELL_META = /[;&|`$(){}[\]<>!#\\]/;
const PATH_TRAVERSAL = /\.\.[/\\]/;
const IDENTIFIER_RE = /^[a-zA-Z0-9_][a-zA-Z0-9_\-.:]{0,127}$/;
const GIT_REF_RE = /^[a-zA-Z0-9_][a-zA-Z0-9_\-.:~^/]{0,255}$/;
const NPM_PACKAGE_RE = /^(@[a-zA-Z0-9_\-]+\/)?[a-zA-Z0-9_\-][a-zA-Z0-9_\-.]{0,213}$/;

export interface ValidationResult {
  valid: boolean;
  sanitized: string;
  error?: string;
}

/**
 * Validate an identifier (agent ID, agent type, namespace, key, etc.)
 * Rejects shell metacharacters and path traversal.
 */
export function validateIdentifier(value: unknown, label: string): ValidationResult {
  if (typeof value !== 'string' || value.length === 0) {
    return { valid: false, sanitized: '', error: `${label} must be a non-empty string` };
  }
  if (value.length > 128) {
    return { valid: false, sanitized: '', error: `${label} exceeds 128 characters` };
  }
  if (SHELL_META.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains disallowed characters` };
  }
  if (PATH_TRAVERSAL.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains path traversal` };
  }
  if (!IDENTIFIER_RE.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains invalid characters (allowed: alphanumeric, _, -, ., :)` };
  }
  return { valid: true, sanitized: value };
}

/**
 * Validate a git ref (HEAD~1, main..feature, commit hashes, etc.).
 * Allows ~, ^, and / which are standard git revision selectors.
 */
export function validateGitRef(value: unknown, label: string): ValidationResult {
  if (typeof value !== 'string' || value.length === 0) {
    return { valid: false, sanitized: '', error: `${label} must be a non-empty string` };
  }
  if (value.length > 256) {
    return { valid: false, sanitized: '', error: `${label} exceeds 256 characters` };
  }
  if (SHELL_META.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains disallowed characters` };
  }
  if (!GIT_REF_RE.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains invalid characters (allowed: alphanumeric, _, -, ., :, ~, ^, /)` };
  }
  return { valid: true, sanitized: value };
}

/**
 * Validate an npm package name (allows @scope/name format).
 */
export function validatePackageName(value: unknown, label: string): ValidationResult {
  if (typeof value !== 'string' || value.length === 0) {
    return { valid: false, sanitized: '', error: `${label} must be a non-empty string` };
  }
  if (value.length > 214) {
    return { valid: false, sanitized: '', error: `${label} exceeds 214 characters` };
  }
  if (SHELL_META.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains disallowed characters` };
  }
  if (!NPM_PACKAGE_RE.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains invalid characters (expected npm package name, e.g. @scope/name)` };
  }
  return { valid: true, sanitized: value };
}

// Path-specific shell-meta check: backslash is a legitimate Windows path
// separator (e.g. `E:\Repos\app\file.ts`) and Claude Code's hook events
// deliver absolute paths in `tool_input.file_path` with backslashes on
// Windows. The general SHELL_META set includes `\` for identifier safety,
// but paths are not shell-expanded — normalizing to forward slashes for
// the check keeps every other shell metacharacter rejected while letting
// absolute Windows paths through (#2352).
const PATH_SHELL_META = /[;&|`$(){}[\]<>!#]/;

/**
 * Validate a file path (prevents traversal and shell injection).
 */
export function validatePath(value: unknown, label: string): ValidationResult {
  if (typeof value !== 'string' || value.length === 0) {
    return { valid: false, sanitized: '', error: `${label} must be a non-empty string` };
  }
  if (value.length > 4096) {
    return { valid: false, sanitized: '', error: `${label} exceeds 4096 characters` };
  }
  if (PATH_TRAVERSAL.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains path traversal (..)` };
  }
  if (PATH_SHELL_META.test(value)) {
    return { valid: false, sanitized: '', error: `${label} contains shell metacharacters` };
  }
  // Normalize Windows backslashes to forward slashes in the sanitized value
  // so downstream consumers see a single path shape regardless of OS.
  const sanitized = value.replace(/\\/g, '/');
  return { valid: true, sanitized };
}

/**
 * Validate a free-text string (description, value, etc.)
 * Allows most characters but rejects shell metacharacters that could cause injection.
 */
export function validateText(value: unknown, label: string, maxLen = 10_000): ValidationResult {
  if (typeof value !== 'string') {
    return { valid: false, sanitized: '', error: `${label} must be a string` };
  }
  if (value.length > maxLen) {
    return { valid: false, sanitized: '', error: `${label} exceeds ${maxLen} characters` };
  }
  // Strip null bytes
  const sanitized = value.replace(/\0/g, '');
  return { valid: true, sanitized };
}

/**
 * Names that let an attacker pivot a child process before any user code runs:
 * shared-library injection on Linux/macOS, Node hooks, and command resolution.
 *
 * audit_1776853149979: terminal_create previously merged caller-supplied env
 * straight into execSync's environment for every subsequent command in the
 * session. Setting LD_PRELOAD or NODE_OPTIONS via that path is functionally
 * equivalent to remote code execution, so the env input needs an allowlist
 * shape and a denylist on these specific names.
 */
const DENYLISTED_ENV_NAMES = new Set([
  'LD_PRELOAD',
  'LD_LIBRARY_PATH',
  'LD_AUDIT',
  'DYLD_INSERT_LIBRARIES',
  'DYLD_LIBRARY_PATH',
  'DYLD_FALLBACK_LIBRARY_PATH',
  'DYLD_FORCE_FLAT_NAMESPACE',
  'NODE_OPTIONS',
  'NODE_PATH',
]);
const ENV_NAME_RE = /^[A-Za-z_][A-Za-z0-9_]{0,127}$/;

export interface EnvValidationResult {
  valid: boolean;
  sanitized: Record<string, string>;
  error?: string;
}

/**
 * Validate a Record<string,string> of environment variables: enforce POSIX
 * names, reject hijack-prone names (LD_PRELOAD, NODE_OPTIONS, …), forbid null
 * bytes in values, and cap value length so a malicious caller can't bloat the
 * stored session past reasonable bounds.
 */
export function validateEnv(value: unknown, label = 'env'): EnvValidationResult {
  if (value === undefined || value === null) {
    return { valid: true, sanitized: {} };
  }
  if (typeof value !== 'object' || Array.isArray(value)) {
    return { valid: false, sanitized: {}, error: `${label} must be an object of string→string` };
  }
  const out: Record<string, string> = {};
  for (const [name, rawVal] of Object.entries(value as Record<string, unknown>)) {
    if (!ENV_NAME_RE.test(name)) {
      return { valid: false, sanitized: {}, error: `${label} key "${name}" is not a valid POSIX env name` };
    }
    if (DENYLISTED_ENV_NAMES.has(name)) {
      return { valid: false, sanitized: {}, error: `${label} key "${name}" is denylisted (loader/runtime hijack)` };
    }
    if (typeof rawVal !== 'string') {
      return { valid: false, sanitized: {}, error: `${label}["${name}"] must be a string` };
    }
    if (rawVal.length > 32_768) {
      return { valid: false, sanitized: {}, error: `${label}["${name}"] exceeds 32768 characters` };
    }
    if (rawVal.includes('\0')) {
      return { valid: false, sanitized: {}, error: `${label}["${name}"] contains a null byte` };
    }
    out[name] = rawVal;
  }
  return { valid: true, sanitized: out };
}

/**
 * Assert validation or throw with a structured error.
 */
export function assertValid(result: ValidationResult): string {
  if (!result.valid) {
    throw new Error(`Validation failed: ${result.error}`);
  }
  return result.sanitized;
}

// Try to load the full @claude-flow/security module for enhanced validation
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let _securityModule: Record<string, any> | null = null;
let _securityLoaded = false;

async function getSecurityModule(): Promise<Record<string, any> | null> {
  if (_securityLoaded) return _securityModule;
  _securityLoaded = true;
  try {
    // Dynamic import — @claude-flow/security is an optional dependency
    _securityModule = await (Function('return import("@claude-flow/security")')() as Promise<Record<string, any>>);
  } catch {
    // @claude-flow/security is optional — fallback to inline validation above
  }
  return _securityModule;
}

/**
 * Enhanced validation using @claude-flow/security Zod schemas when available.
 * Falls back to inline regex validation otherwise.
 */
export async function validateAgentSpawn(input: Record<string, unknown>): Promise<{ valid: boolean; errors: string[] }> {
  const errors: string[] = [];

  // Always run inline validation
  if (input.agentType) {
    const r = validateIdentifier(input.agentType, 'agentType');
    if (!r.valid) errors.push(r.error!);
  }
  if (input.agentId) {
    const r = validateIdentifier(input.agentId, 'agentId');
    if (!r.valid) errors.push(r.error!);
  }
  if (input.domain) {
    const r = validateIdentifier(input.domain, 'domain');
    if (!r.valid) errors.push(r.error!);
  }

  // Try enhanced Zod validation if available.
  // Fix for #1567: @claude-flow/security's SpawnAgentSchema expects `type` and
  // `id` (not `agentType`/`name`), so the previous call always failed with
  // "type: Required". Also swallow `invalid_enum_value` errors because the
  // schema enumerates only 15 built-in agent types — we support custom types
  // (the inline validator already checked the identifier is safe).
  const sec = await getSecurityModule();
  if (sec?.SpawnAgentSchema) {
    try {
      sec.SpawnAgentSchema.parse({
        type: input.agentType,
        id: input.agentId,
      });
    } catch (zodErr: any) {
      if (zodErr.issues) {
        for (const issue of zodErr.issues) {
          if (issue.code === 'invalid_enum_value') continue;
          errors.push(`${issue.path.join('.')}: ${issue.message}`);
        }
      }
    }
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Memory backend abstraction (ADR-100 alpha.1).
 *
 * Defines the contract that any memory implementation in the Claude Flow
 * ecosystem must satisfy. cli-core ships JsonMemoryBackend (this directory)
 * for the lite path; @claude-flow/cli ships SqliteHnswMemoryBackend (heavy
 * path with vector search) which implements the same interface.
 *
 * Plugins / scripts that only need basic key-value persistence
 * (cost-tracker's session records, budget config, etc.) work against this
 * interface — semantic search degrades to substring fallback in the lite
 * backend, but every other operation is feature-complete.
 */

export interface MemoryEntry {
  key: string;
  value: unknown;
  namespace: string;
  tags: string[];
  storedAt: string;          // ISO timestamp
  accessCount: number;
  lastAccessed: string;      // ISO timestamp
  ttlSeconds?: number;       // optional time-to-live (relative to storedAt)
}

export interface MemorySearchResult extends MemoryEntry {
  /**
   * Similarity score [0, 1]. The lite (JSON) backend produces a substring-
   * match score (1.0 = exact substring, 0 < x < 1 = fuzzy). The heavy
   * (SQLite/HNSW) backend produces a true cosine similarity from the vector
   * index. Callers ranking by score should treat the value as backend-
   * specific — comparing scores across backends is meaningless.
   */
  score: number;

  /** Which backend produced this result. Useful for observability. */
  backend: 'json' | 'sqlite-hnsw' | string;
}

export interface StoreOptions {
  namespace?: string;        // default: "default"
  tags?: string[];
  ttl?: number;              // seconds; expires at storedAt + ttl
  upsert?: boolean;          // default: false (UNIQUE-constraint behavior)
}

export interface SearchOptions {
  namespace?: string;
  limit?: number;            // default: 10
  threshold?: number;        // default: 0 (lite backend) or 0.3 (heavy)
}

export interface ListOptions {
  namespace?: string;
  limit?: number;            // default: 100
  tags?: string[];           // intersection filter
}

export interface MemoryStats {
  totalEntries: number;
  namespaces: string[];
  sizeBytes: number;         // approximate on-disk size
  backend: string;
}

/**
 * The contract every memory backend implements.
 * All methods are async to allow for I/O-heavy or remote backends.
 */
export interface MemoryBackend {
  /**
   * Store a value under (namespace, key). If a record exists at that
   * coordinate AND opts.upsert is false (default), throws a UNIQUE-constraint
   * error. With upsert: true, replaces.
   */
  store(key: string, value: unknown, opts?: StoreOptions): Promise<void>;

  /**
   * Read by exact (namespace, key). Returns null on miss.
   * Increments accessCount + lastAccessed.
   */
  retrieve(key: string, opts?: { namespace?: string }): Promise<MemoryEntry | null>;

  /**
   * Search by query. Lite backend = substring match (score=1 for exact
   * substring, 0.5 for case-insensitive partial); heavy backend = cosine
   * similarity over HNSW. Both honor namespace + threshold + limit.
   */
  search(query: string, opts?: SearchOptions): Promise<MemorySearchResult[]>;

  /**
   * Enumerate entries (with optional namespace + tag filtering).
   * Does NOT increment accessCount.
   */
  list(opts?: ListOptions): Promise<MemoryEntry[]>;

  /**
   * Remove an entry by exact (namespace, key). Returns true if deleted,
   * false if no such entry existed.
   */
  delete(key: string, opts?: { namespace?: string }): Promise<boolean>;

  /**
   * Backend health + size summary. Used by `memory stats` CLI subcommand.
   */
  stats(): Promise<MemoryStats>;

  /**
   * Backend identifier. cli-core's JSON backend returns 'json'; cli's
   * SQLite/HNSW backend returns 'sqlite-hnsw'. Used for observability and
   * for `memory_search` MCP-tool callers that want to know which scoring
   * regime they're dealing with.
   */
  readonly id: string;
}

/**
 * JsonMemoryBackend — the lite memory implementation that ships in cli-core.
 *
 * Persists entries to a JSON file (default: `.swarm/memory.json`, override
 * via CLAUDE_FLOW_MEMORY_PATH). No SQLite, no HNSW, no ONNX embeddings —
 * deliberately so that cli-core stays under 250 KB packed.
 *
 * Search degrades to substring matching (case-insensitive). For real
 * semantic search install @claude-flow/cli (the heavy SqliteHnswMemoryBackend
 * implements the same interface).
 *
 * Atomicity: every write goes through a temp file + atomic rename. No
 * inflight reader sees a half-written JSON. Concurrent writers across
 * processes are NOT coordinated — the last writer wins. Acceptable for
 * single-developer plugin workloads; not safe under high write contention.
 */

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import type {
  MemoryBackend,
  MemoryEntry,
  MemorySearchResult,
  MemoryStats,
  StoreOptions,
  SearchOptions,
  ListOptions,
} from './backend.js';

const DEFAULT_PATH = '.swarm/memory.json';

interface FileShape {
  version: 1;
  backend: 'json';
  entries: Record<string, MemoryEntry>; // key: `${namespace}::${key}`
  createdAt: string;
  updatedAt: string;
}

function compositeKey(namespace: string, key: string): string {
  return `${namespace}::${key}`;
}

function nowIso(): string {
  return new Date().toISOString();
}

export class JsonMemoryBackend implements MemoryBackend {
  readonly id = 'json';
  private readonly path: string;
  private cache: FileShape | null = null;

  constructor(opts?: { path?: string }) {
    this.path = resolve(opts?.path || process.env.CLAUDE_FLOW_MEMORY_PATH || DEFAULT_PATH);
  }

  private load(): FileShape {
    if (this.cache) return this.cache;
    if (!existsSync(this.path)) {
      const fresh: FileShape = {
        version: 1,
        backend: 'json',
        entries: {},
        createdAt: nowIso(),
        updatedAt: nowIso(),
      };
      this.cache = fresh;
      return fresh;
    }
    try {
      const raw = readFileSync(this.path, 'utf-8');
      const parsed = JSON.parse(raw);
      if (parsed.version !== 1) {
        throw new Error(`Unsupported memory file version: ${parsed.version}`);
      }
      this.cache = parsed;
      return parsed;
    } catch (err) {
      throw new Error(`memory: failed to load ${this.path}: ${(err as Error).message}`);
    }
  }

  private save(state: FileShape): void {
    state.updatedAt = nowIso();
    this.cache = state;
    const dir = dirname(this.path);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }
    const tmp = `${this.path}.tmp.${process.pid}.${Date.now()}`;
    writeFileSync(tmp, JSON.stringify(state, null, 2), 'utf-8');
    renameSync(tmp, this.path);
  }

  private isExpired(entry: MemoryEntry): boolean {
    if (!entry.ttlSeconds) return false;
    const expiresAt = new Date(entry.storedAt).getTime() + entry.ttlSeconds * 1000;
    return Date.now() > expiresAt;
  }

  async store(key: string, value: unknown, opts?: StoreOptions): Promise<void> {
    const namespace = opts?.namespace || 'default';
    const ck = compositeKey(namespace, key);
    const state = this.load();
    if (state.entries[ck] && !opts?.upsert) {
      throw new Error(`memory: UNIQUE constraint failed for namespace='${namespace}' key='${key}' (pass --upsert to overwrite)`);
    }
    state.entries[ck] = {
      key,
      value,
      namespace,
      tags: opts?.tags || [],
      storedAt: nowIso(),
      accessCount: 0,
      lastAccessed: nowIso(),
      ttlSeconds: opts?.ttl,
    };
    this.save(state);
  }

  async retrieve(key: string, opts?: { namespace?: string }): Promise<MemoryEntry | null> {
    const namespace = opts?.namespace || 'default';
    const ck = compositeKey(namespace, key);
    const state = this.load();
    const entry = state.entries[ck];
    if (!entry) return null;
    if (this.isExpired(entry)) {
      delete state.entries[ck];
      this.save(state);
      return null;
    }
    entry.accessCount++;
    entry.lastAccessed = nowIso();
    this.save(state);
    return { ...entry };
  }

  async search(query: string, opts?: SearchOptions): Promise<MemorySearchResult[]> {
    const namespace = opts?.namespace;
    const limit = opts?.limit ?? 10;
    const threshold = opts?.threshold ?? 0;
    const q = query.toLowerCase();
    const state = this.load();
    const out: MemorySearchResult[] = [];
    for (const entry of Object.values(state.entries)) {
      if (this.isExpired(entry)) continue;
      if (namespace && entry.namespace !== namespace) continue;
      // Simple substring scoring:
      //   1.0  → exact substring of key OR exact substring of value (string form)
      //   0.5  → case-insensitive partial (currently the same — kept distinct so
      //          the heavy backend's similarity scoring can map cleanly)
      //   0    → no match
      const haystack = `${entry.key} ${JSON.stringify(entry.value)}`.toLowerCase();
      let score = 0;
      if (haystack.includes(q)) score = 1.0;
      if (score < threshold) continue;
      out.push({ ...entry, score, backend: 'json' });
    }
    out.sort((a, b) => b.score - a.score);
    return out.slice(0, limit);
  }

  async list(opts?: ListOptions): Promise<MemoryEntry[]> {
    const namespace = opts?.namespace;
    const limit = opts?.limit ?? 100;
    const tags = opts?.tags;
    const state = this.load();
    const out: MemoryEntry[] = [];
    for (const entry of Object.values(state.entries)) {
      if (this.isExpired(entry)) continue;
      if (namespace && entry.namespace !== namespace) continue;
      if (tags && tags.length > 0) {
        const hasAll = tags.every((t) => entry.tags.includes(t));
        if (!hasAll) continue;
      }
      out.push({ ...entry });
    }
    return out.slice(0, limit);
  }

  async delete(key: string, opts?: { namespace?: string }): Promise<boolean> {
    const namespace = opts?.namespace || 'default';
    const ck = compositeKey(namespace, key);
    const state = this.load();
    if (!state.entries[ck]) return false;
    delete state.entries[ck];
    this.save(state);
    return true;
  }

  async stats(): Promise<MemoryStats> {
    const state = this.load();
    const entries = Object.values(state.entries);
    const namespaces = [...new Set(entries.map((e) => e.namespace))].sort();
    const sizeBytes = existsSync(this.path)
      ? readFileSync(this.path, 'utf-8').length
      : 0;
    return {
      totalEntries: entries.length,
      namespaces,
      sizeBytes,
      backend: this.id,
    };
  }
}

/**
 * V3 CLI Output Formatter
 * Advanced output formatting with tables, progress bars, and colors
 */

import type { TableOptions, TableColumn, ProgressOptions, SpinnerOptions } from './types.js';

// ============================================
// Color Support
// ============================================

const COLORS = {
  // Standard colors
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  italic: '\x1b[3m',
  underline: '\x1b[4m',

  // Foreground colors
  black: '\x1b[30m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  white: '\x1b[37m',
  gray: '\x1b[90m',

  // Bright foreground colors
  brightRed: '\x1b[91m',
  brightGreen: '\x1b[92m',
  brightYellow: '\x1b[93m',
  brightBlue: '\x1b[94m',
  brightMagenta: '\x1b[95m',
  brightCyan: '\x1b[96m',
  brightWhite: '\x1b[97m',

  // Background colors
  bgBlack: '\x1b[40m',
  bgRed: '\x1b[41m',
  bgGreen: '\x1b[42m',
  bgYellow: '\x1b[43m',
  bgBlue: '\x1b[44m',
  bgMagenta: '\x1b[45m',
  bgCyan: '\x1b[46m',
  bgWhite: '\x1b[47m'
} as const;

type ColorName = keyof typeof COLORS;

export type VerbosityLevel = 'quiet' | 'normal' | 'verbose' | 'debug';

export class OutputFormatter {
  private colorEnabled: boolean;
  private outputStream: NodeJS.WriteStream;
  private errorStream: NodeJS.WriteStream;
  private verbosity: VerbosityLevel;

  constructor(options: { color?: boolean; verbosity?: VerbosityLevel } = {}) {
    this.colorEnabled = options.color ?? this.supportsColor();
    this.outputStream = process.stdout;
    this.errorStream = process.stderr;
    this.verbosity = options.verbosity ?? 'normal';
  }

  /**
   * Set verbosity level
   * - quiet: Only errors and direct results
   * - normal: Errors, warnings, info, and results
   * - verbose: All of normal + debug messages
   * - debug: All output including trace
   */
  setVerbosity(level: VerbosityLevel): void {
    this.verbosity = level;
  }

  getVerbosity(): VerbosityLevel {
    return this.verbosity;
  }

  isQuiet(): boolean {
    return this.verbosity === 'quiet';
  }

  isVerbose(): boolean {
    return this.verbosity === 'verbose' || this.verbosity === 'debug';
  }

  isDebug(): boolean {
    return this.verbosity === 'debug';
  }

  private supportsColor(): boolean {
    // Check for NO_COLOR environment variable
    if (process.env.NO_COLOR !== undefined) return false;

    // Check for FORCE_COLOR environment variable
    if (process.env.FORCE_COLOR !== undefined) return true;

    // Check if stdout is a TTY
    return process.stdout.isTTY ?? false;
  }

  // ============================================
  // Color Methods
  // ============================================

  color(text: string, ...colors: ColorName[]): string {
    if (!this.colorEnabled) return text;

    const codes = colors.map(c => COLORS[c]).join('');
    return `${codes}${text}${COLORS.reset}`;
  }

  bold(text: string): string {
    return this.color(text, 'bold');
  }

  dim(text: string): string {
    return this.color(text, 'dim');
  }

  success(text: string): string {
    return this.color(text, 'green');
  }

  error(text: string): string {
    return this.color(text, 'red');
  }

  warning(text: string): string {
    return this.color(text, 'yellow');
  }

  info(text: string): string {
    return this.color(text, 'blue');
  }

  highlight(text: string): string {
    return this.color(text, 'cyan', 'bold');
  }

  // ============================================
  // Output Methods
  // ============================================

  write(text: string): void {
    this.outputStream.write(text);
  }

  writeln(text: string = ''): void {
    this.outputStream.write(text + '\n');
  }

  writeError(text: string): void {
    this.errorStream.write(text);
  }

  writeErrorln(text: string = ''): void {
    this.errorStream.write(text + '\n');
  }

  // ============================================
  // Formatted Output Methods
  // ============================================

  printSuccess(message: string): void {
    // Success always shows (result output)
    const icon = this.color('[OK]', 'green', 'bold');
    this.writeln(`${icon} ${message}`);
  }

  printError(message: string, details?: string): void {
    // Errors always show
    const icon = this.color('[ERROR]', 'red', 'bold');
    this.writeErrorln(`${icon} ${message}`);
    if (details) {
      this.writeErrorln(this.dim(`  ${details}`));
    }
  }

  printWarning(message: string): void {
    // Warnings suppressed in quiet mode
    if (this.verbosity === 'quiet') return;
    const icon = this.color('[WARN]', 'yellow', 'bold');
    this.writeln(`${icon} ${message}`);
  }

  printInfo(message: string): void {
    // Info suppressed in quiet mode
    if (this.verbosity === 'quiet') return;
    const icon = this.color('[INFO]', 'blue', 'bold');
    this.writeln(`${icon} ${message}`);
  }

  printDebug(message: string): void {
    // Debug only shows in verbose/debug mode
    if (this.verbosity !== 'verbose' && this.verbosity !== 'debug') return;
    const icon = this.color('[DEBUG]', 'gray');
    this.writeln(`${icon} ${this.dim(message)}`);
  }

  printTrace(message: string): void {
    // Trace only shows in debug mode
    if (this.verbosity !== 'debug') return;
    const icon = this.color('[TRACE]', 'gray', 'dim');
    this.writeln(`${icon} ${this.dim(message)}`);
  }

  // ============================================
  // Table Formatting
  // ============================================

  table(options: TableOptions): string {
    const { columns, data, border = true, header = true, padding = 1, maxWidth } = options;

    // Calculate column widths
    const widths = this.calculateColumnWidths(columns, data, maxWidth);

    const lines: string[] = [];
    const pad = ' '.repeat(padding);

    // Border characters
    const borderChars = border ? {
      topLeft: '+', topRight: '+', bottomLeft: '+', bottomRight: '+',
      horizontal: '-', vertical: '|',
      leftT: '+', rightT: '+', topT: '+', bottomT: '+', cross: '+'
    } : {
      topLeft: '', topRight: '', bottomLeft: '', bottomRight: '',
      horizontal: '', vertical: ' ',
      leftT: '', rightT: '', topT: '', bottomT: '', cross: ''
    };

    // Top border
    if (border) {
      lines.push(this.createBorderLine(widths, borderChars, 'top', padding));
    }

    // Header row
    if (header) {
      const headerRow = columns.map((col, i) => {
        const text = this.truncate(col.header, widths[i]);
        return pad + this.alignText(this.bold(text), widths[i], col.align) + pad;
      }).join(borderChars.vertical);

      lines.push(`${borderChars.vertical}${headerRow}${borderChars.vertical}`);

      // Header separator
      if (border) {
        lines.push(this.createBorderLine(widths, borderChars, 'middle', padding));
      }
    }

    // Data rows
    for (const row of data) {
      const rowCells = columns.map((col, i) => {
        let value = row[col.key];

        // Apply formatter if provided
        if (col.format) {
          value = col.format(value);
        } else {
          value = String(value ?? '');
        }

        const text = this.truncate(String(value), widths[i]);
        return pad + this.alignText(text, widths[i], col.align) + pad;
      }).join(borderChars.vertical);

      lines.push(`${borderChars.vertical}${rowCells}${borderChars.vertical}`);
    }

    // Bottom border
    if (border) {
      lines.push(this.createBorderLine(widths, borderChars, 'bottom', padding));
    }

    return lines.join('\n');
  }

  printTable(options: TableOptions): void {
    this.writeln(this.table(options));
  }

  private calculateColumnWidths(
    columns: TableColumn[],
    data: Record<string, unknown>[],
    maxWidth?: number
  ): number[] {
    const widths = columns.map((col, i) => {
      // Start with header width
      let width = col.header.length;

      // Check all data values
      for (const row of data) {
        let value = row[col.key];
        if (col.format) {
          value = col.format(value);
        }
        const len = this.stripAnsi(String(value ?? '')).length;
        width = Math.max(width, len);
      }

      // Apply column-specific width limit
      if (col.width) {
        width = Math.min(width, col.width);
      }

      return width;
    });

    // Apply max width constraint
    if (maxWidth) {
      const totalWidth = widths.reduce((a, b) => a + b, 0) + (columns.length * 3) + 1;
      if (totalWidth > maxWidth) {
        const reduction = (totalWidth - maxWidth) / columns.length;
        return widths.map(w => Math.max(3, Math.floor(w - reduction)));
      }
    }

    return widths;
  }

  private createBorderLine(
    widths: number[],
    chars: Record<string, string>,
    position: 'top' | 'middle' | 'bottom',
    padding: number
  ): string {
    const cellWidth = (w: number) => chars.horizontal.repeat(w + (padding * 2));
    const cells = widths.map(cellWidth).join(
      position === 'top' ? chars.topT :
      position === 'bottom' ? chars.bottomT :
      chars.cross
    );

    const left = position === 'top' ? chars.topLeft : position === 'bottom' ? chars.bottomLeft : chars.leftT;
    const right = position === 'top' ? chars.topRight : position === 'bottom' ? chars.bottomRight : chars.rightT;

    return `${left}${cells}${right}`;
  }

  private alignText(text: string, width: number, align: 'left' | 'center' | 'right' = 'left'): string {
    const len = this.stripAnsi(text).length;
    const padding = width - len;

    if (padding <= 0) return text;

    switch (align) {
      case 'right':
        return ' '.repeat(padding) + text;
      case 'center':
        const left = Math.floor(padding / 2);
        const right = padding - left;
        return ' '.repeat(left) + text + ' '.repeat(right);
      default:
        return text + ' '.repeat(padding);
    }
  }

  private truncate(text: string, maxLength: number): string {
    const stripped = this.stripAnsi(text);
    if (stripped.length <= maxLength) return text;
    return stripped.slice(0, maxLength - 3) + '...';
  }

  private stripAnsi(text: string): string {
    return text.replace(/\x1b\[[0-9;]*m/g, '');
  }

  // ============================================
  // Progress Bar
  // ============================================

  createProgress(options: ProgressOptions): Progress {
    return new Progress(this, options);
  }

  progressBar(current: number, total: number, width: number = 40): string {
    const percent = Math.min(100, Math.max(0, (current / total) * 100));
    const filled = Math.round((width * percent) / 100);
    const empty = width - filled;

    const bar = this.color('#'.repeat(filled), 'green') +
                this.dim('-'.repeat(empty));

    return `[${bar}] ${percent.toFixed(1)}%`;
  }

  // ============================================
  // Spinner
  // ============================================

  createSpinner(options: SpinnerOptions): Spinner {
    return new Spinner(this, options);
  }

  // ============================================
  // JSON Output
  // ============================================

  json(data: unknown, pretty: boolean = true): string {
    return pretty ? JSON.stringify(data, null, 2) : JSON.stringify(data);
  }

  printJson(data: unknown, pretty: boolean = true): void {
    this.writeln(this.json(data, pretty));
  }

  // ============================================
  // List Output
  // ============================================

  list(items: string[], bullet: string = '-'): string {
    return items.map(item => `  ${bullet} ${item}`).join('\n');
  }

  printList(items: string[], bullet: string = '-'): void {
    this.writeln(this.list(items, bullet));
  }

  numberedList(items: string[]): string {
    return items.map((item, i) => `  ${i + 1}. ${item}`).join('\n');
  }

  printNumberedList(items: string[]): void {
    this.writeln(this.numberedList(items));
  }

  // ============================================
  // Box Output
  // ============================================

  box(content: string, title?: string): string {
    const lines = content.split('\n');
    const maxLen = Math.max(...lines.map(l => this.stripAnsi(l).length), title?.length ?? 0);
    const width = maxLen + 4;

    const border = {
      topLeft: '+', topRight: '+',
      bottomLeft: '+', bottomRight: '+',
      horizontal: '-', vertical: '|'
    };

    const result: string[] = [];

    // Top border with optional title
    if (title) {
      const titleText = ` ${title} `;
      const leftPad = Math.floor((width - titleText.length - 2) / 2);
      const rightPad = width - titleText.length - leftPad - 2;
      result.push(
        border.topLeft +
        border.horizontal.repeat(leftPad) +
        this.bold(titleText) +
        border.horizontal.repeat(rightPad) +
        border.topRight
      );
    } else {
      result.push(border.topLeft + border.horizontal.repeat(width - 2) + border.topRight);
    }

    // Content lines
    for (const line of lines) {
      const stripped = this.stripAnsi(line);
      const padding = maxLen - stripped.length;
      result.push(`${border.vertical} ${line}${' '.repeat(padding)} ${border.vertical}`);
    }

    // Bottom border
    result.push(border.bottomLeft + border.horizontal.repeat(width - 2) + border.bottomRight);

    return result.join('\n');
  }

  printBox(content: string, title?: string): void {
    this.writeln(this.box(content, title));
  }

  setColorEnabled(enabled: boolean): void {
    this.colorEnabled = enabled;
  }

  isColorEnabled(): boolean {
    return this.colorEnabled;
  }
}

// ============================================
// Progress Class
// ============================================

export class Progress {
  private current: number;
  private total: number;
  private width: number;
  private startTime: number;
  private formatter: OutputFormatter;
  private showPercentage: boolean;
  private showETA: boolean;
  private lastRender: string = '';

  constructor(formatter: OutputFormatter, options: ProgressOptions) {
    this.formatter = formatter;
    this.current = options.current ?? 0;
    this.total = options.total;
    this.width = options.width ?? 40;
    this.showPercentage = options.showPercentage ?? true;
    this.showETA = options.showETA ?? true;
    this.startTime = Date.now();
  }

  update(current: number): void {
    this.current = current;
    this.render();
  }

  increment(amount: number = 1): void {
    this.update(this.current + amount);
  }

  render(): void {
    const bar = this.formatter.progressBar(this.current, this.total, this.width);

    let output = bar;

    if (this.showETA && this.current > 0) {
      const elapsed = Date.now() - this.startTime;
      const rate = this.current / elapsed;
      const remaining = this.total - this.current;
      const eta = remaining / rate;

      if (isFinite(eta)) {
        output += ` ETA: ${this.formatTime(eta)}`;
      }
    }

    // Clear previous line and write new
    if (this.lastRender) {
      process.stdout.write('\r' + ' '.repeat(this.lastRender.length) + '\r');
    }

    process.stdout.write(output);
    this.lastRender = output;
  }

  finish(): void {
    this.current = this.total;
    this.render();
    process.stdout.write('\n');
  }

  private formatTime(ms: number): string {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);

    if (hours > 0) {
      return `${hours}h ${minutes % 60}m`;
    } else if (minutes > 0) {
      return `${minutes}m ${seconds % 60}s`;
    } else {
      return `${seconds}s`;
    }
  }
}

// ============================================
// Spinner Class
// ============================================

export class Spinner {
  private formatter: OutputFormatter;
  private text: string;
  private frames: string[];
  private interval: ReturnType<typeof setInterval> | null = null;
  private frameIndex: number = 0;

  private static readonly SPINNERS: Record<string, string[]> = {
    dots: ['...', '..:' , '.::', ':::',  '::.', ':..' ,],
    line: ['-', '\\', '|', '/'],
    arc: ['◜', '◠', '◝', '◞', '◡', '◟'],
    circle: ['◐', '◓', '◑', '◒'],
    arrows: ['←', '↖', '↑', '↗', '→', '↘', '↓', '↙']
  };

  constructor(formatter: OutputFormatter, options: SpinnerOptions) {
    this.formatter = formatter;
    this.text = options.text;
    this.frames = Spinner.SPINNERS[options.spinner ?? 'dots'];
  }

  start(): void {
    if (this.interval) return;

    this.interval = setInterval(() => {
      this.render();
      this.frameIndex = (this.frameIndex + 1) % this.frames.length;
    }, 100);
    this.interval.unref();

    this.render();
  }

  stop(message?: string): void {
    if (this.interval) {
      clearInterval(this.interval);
      this.interval = null;
    }

    // Clear the line
    process.stdout.write('\r' + ' '.repeat(this.text.length + 10) + '\r');

    if (message) {
      this.formatter.writeln(message);
    }
  }

  succeed(message?: string): void {
    this.stop(this.formatter.success(message ?? this.text));
  }

  fail(message?: string): void {
    this.stop(this.formatter.error(message ?? this.text));
  }

  private render(): void {
    const frame = this.formatter.info(this.frames[this.frameIndex]);
    process.stdout.write(`\r${frame} ${this.text}`);
  }

  setText(text: string): void {
    this.text = text;
  }
}

